#!/usr/bin/env python3
"""This skill reviews an OpenAPI 3 document provided as a JSON file to identify common contract problems. Use this when you need to programmatically chec — generated by YuktiForge from skillspec.yaml. Entry point only; the logic is in skill_logic.py."""
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import skill_logic  # noqa: E402

MAX_BYTES = 5_000_000


class InputError(Exception):
    pass


def run_text(text):
    result = skill_logic.run(text)
    if not isinstance(result, dict):
        raise TypeError("skill_logic.run must return a dict")
    return result


def run_file(path):
    p = Path(path)
    if not p.is_file():
        raise InputError("not a readable file: " + str(path))
    if p.stat().st_size > MAX_BYTES:
        raise InputError("input is larger than %d bytes" % MAX_BYTES)
    try:
        text = p.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise InputError("cannot read input as UTF-8 text: " + type(e).__name__)
    return run_text(text)


def main(argv):
    if len(argv) != 2:
        sys.stderr.write("usage: scripts/api_contract_reviewer.py <input-file>\n")
        return 2
    try:
        result = run_file(argv[1])
    except InputError as e:
        sys.stderr.write("input error: %s\n" % e)
        return 2
    except Exception as e:  # the logic is generated code: never leak a traceback with paths
        sys.stderr.write("internal error: %s: %s\n" % (type(e).__name__, " ".join(str(e).split())[:160]))
        return 1
    sys.stdout.write(json.dumps(result, indent=2, sort_keys=True, ensure_ascii=False) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
